/**
 * @beta
 * 用于缩小一组声音定义范围的条件。每个
 * 字段都是可选的，且仅当定义时应用其约束；
 * 定义必须满足每个已定义的字段才能
 * 通过。
 */
export interface SoundDefinitionFilter {
    /**
     * @remarks
     * 艺术家名称，用于与定义的
     * music_info.artist 匹配。比较不区分大小写。当
     * 定义为非空数组时，定义仅当
     * 其声明的艺术家与提供的某个值匹配时才通过。当
     * 未定义时，不应用对艺术家的任何约束。
     *
     */
    artists?: string[];
    /**
     * @remarks
     * 要与定义的 music_info.genres 匹配的流派。
     * 比较不区分大小写。当定义为非空
     * 数组时，定义仅当其中至少有一个
     * 声明的流派与提供的某个值匹配时才通过。当
     * 未定义时，不应用对流派的任何约束。
     *
     */
    genres?: string[];
    /**
     * @remarks
     * 以秒为单位的上限，包含该值。当定义时，
     * 持续时间更长的定义以及未声明
     * 持续时间的定义都会被排除。当未定义时，不应用
     * 上限。
     *
     */
    maxDuration?: number;
    /**
     * @remarks
     * 以秒为单位的下限，包含该值。当定义时，
     * 持续时间更短的定义以及未声明
     * 持续时间的定义都会被排除。当未定义时，不应用
     * 下限。
     *
     */
    minDuration?: number;
    /**
     * @remarks
     * 要与定义的 music_info.moods 匹配的情绪。
     * 比较不区分大小写。当定义为非空
     * 数组时，定义仅当其中至少有一个
     * 声明的情绪与提供的某个值匹配时才通过。当
     * 未定义时，不应用对情绪的任何约束。
     *
     */
    moods?: string[];
    /**
     * @remarks
     * 要与定义的 tags 匹配的标签约束。
     * 标签名和值的比较不区分大小写。
     * 当定义为非空记录时，定义仅通过
     * 当对于每个具有非空值数组的条目，标签
     * 名称出现在定义中，且至少有一个匹配的
     * 值。未定义时，不应用对标签的任何约束。
     *
     */
    tags?: Record<string, string[]>;
    /**
     * @remarks
     * 要与定义的 music_info.title 匹配的标题。
     * 比较不区分大小写。当定义为非空
     * 数组时，定义仅在其声明的标题
     * 与提供的某个值匹配时才通过。当未定义时，
     * 不应用对标题的任何约束。
     *
     */
    titles?: string[];
}